    flutter += cloth(p, vec2(0.372, 0.629), vec2(0.255, 0.770), 0.075, t, 2.1, wind);        // knight's red cape
    flutter += cloth(p, vec2(0.518, 0.700), vec2(0.440, 0.775), 0.048, t, 3.4, wind);        // archer's cloak
